package ds.seed5503;

import ds.MaxMin4;
import org.junit.Test;
import org.junit.experimental.categories.Category;

import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

/**
 * Marker interface for categorizing unit tests in this package.
 */
interface UnitTest {}

/**
 * Improved and documented tests for MaxMin4 behaviors.
 *
 * <p>These tests were refactored from an autogenerated baseline to provide
 * clearer Given-When-Then structure, requirement references, and more
 * descriptive assertions. Each test keeps its original name for compatibility
 * with existing test runners but includes expanded checks and documentation.
 *
 * Requirement references:
 * - REQ-004: MaxMin4 must handle invalid index ranges by throwing ArrayIndexOutOfBoundsException.
 * - REQ-010: Instantiation of MaxMin4 should produce a concrete non-null object.
 */
@Category(UnitTest.class)
public class EvoAITest {

    /**
     * Functional interface to support executing code that can throw checked exceptions
     * within our custom expectThrows implementation.
     */
    @FunctionalInterface
    private static interface ThrowingRunnable {
        void run() throws Throwable;
    }

    /**
     * Helper that asserts a specific exception is thrown by the supplied action.
     * Returns the caught exception for further assertions.
     *
     * This avoids depending on a particular JUnit version's assertThrows and provides
     * clear failure messages.
     */
    private static <T extends Throwable> T expectThrows(Class<T> expectedType, ThrowingRunnable action) {
        try {
            action.run();
            fail("Expected exception of type " + expectedType.getName() + " to be thrown, but nothing was thrown.");
            return null; // unreachable
        } catch (Throwable thrown) {
            if (!expectedType.isInstance(thrown)) {
                String msg = String.format("Expected exception of type %s but got %s: %s",
                        expectedType.getName(), thrown.getClass().getName(), thrown.getMessage());
                fail(msg);
            }
            return expectedType.cast(thrown);
        }
    }

    /**
     * test0
     *
     * Given: an integer array of length 9 with one element set to 1491.
     * When:  maxMin4 is invoked with a valid start index (0) and an absurdly large end index (2278).
     * Then:  an ArrayIndexOutOfBoundsException must be thrown and the input array must remain unchanged.
     *
     * Requirement: REQ-004
     */
    @Test(timeout = 4000)
    public void test0() throws Throwable {
        // Given
        int[] intArray0 = new int[9];
        intArray0[2] = 1491;
        int[] snapshot = intArray0.clone();

        // When / Then
        ArrayIndexOutOfBoundsException ex = expectThrows(ArrayIndexOutOfBoundsException.class,
                () -> MaxMin4.maxMin4(intArray0, 0, 2278));

        // Assert exception was thrown (type checked by helper) and array unchanged
        assertNotNull("Expected an ArrayIndexOutOfBoundsException to be thrown, but caught null.", ex);
        assertArrayEquals("Input array must not be modified when an exception is thrown.", snapshot, intArray0);
    }

    /**
     * test1
     *
     * Given: an integer array of length 9 with the first element set to -1.
     * When:  maxMin4 is invoked with a start index of 0 and an invalid end index (2278).
     * Then:  an ArrayIndexOutOfBoundsException must be thrown and the array's contents must be preserved.
     *
     * Requirement: REQ-004
     */
    @Test(timeout = 4000)
    public void test1() throws Throwable {
        // Given
        int[] intArray0 = new int[9];
        intArray0[0] = -1;
        int[] snapshot = intArray0.clone();

        // When / Then
        ArrayIndexOutOfBoundsException ex = expectThrows(ArrayIndexOutOfBoundsException.class,
                () -> MaxMin4.maxMin4(intArray0, 0, 2278));

        // Assert exception and array invariants
        assertNotNull("Expected an ArrayIndexOutOfBoundsException to be thrown.", ex);
        assertArrayEquals("Array contents should be preserved after the method throws.", snapshot, intArray0);
        assertEquals("The first element should remain -1 after the failed call.", -1, intArray0[0]);
    }

    /**
     * test2
     *
     * Given: no special preconditions.
     * When:  a MaxMin4 instance is constructed.
     * Then:  the instance must be non-null and of the expected type.
     *
     * Requirement: REQ-010
     */
    @Test(timeout = 4000)
    public void test2() throws Throwable {
        // Given / When
        MaxMin4 maxMin4_0 = new MaxMin4();

        // Then - basic sanity checks on construction
        assertNotNull("Constructor should produce a non-null MaxMin4 instance.", maxMin4_0);
        assertEquals("Constructed instance must be of type MaxMin4.", MaxMin4.class, maxMin4_0.getClass());

        // Additional lightweight behavioral check:
        // If the class exposes no-arg behavior, ensure it does not throw on a trivial call.
        // We avoid assuming return types by invoking maxMin4 with a small valid range if possible.
        int[] sample = new int[] {3, 1, 4, 2};
        try {
            // We try to call maxMin4 with a valid range to exercise a happy path if implemented.
            MaxMin4.maxMin4(sample, 0, sample.length - 1);
        } catch (ArrayIndexOutOfBoundsException aioobe) {
            // If this class requires different semantics, we at least assert that the constructor succeeded;
            // treat index errors here as a separate concern already covered by other tests.
        } catch (Throwable t) {
            // If any other runtime exception occurs, fail the test to surface unexpected behavior.
            fail("Unexpected exception when invoking maxMin4 in a basic sanity check: " + t);
        }
    }
}